    ref_individual_actions = set()
    for track in target_individual_tracks:
        target_individual_actions.update(get_unique_actions_from_tracks([track]))
    for track in ref_individual_tracks:
        ref_individual_actions.update(get_unique_actions_from_tracks([track]))
    if len(target_individual_actions) != len(ref_individual_actions):
        return True
    for action in target_individual_actions:
        if action not in ref_individual_actions:
